export function main(ctx) {
  const items = [3, 1, 2];

  // Declarations are hoisted within their block — callable before their line.
  const total = sum(items);

  function sum(xs) {
    return xs.reduce((acc, n) => acc + n, 0);
  }

  // Defaults; a missing argument is null, so the default fills in.
  function label(name, suffix = "!") {
    return name + suffix;
  }

  const doubled = items.map((n) => n * 2);       // arrows: block or expression body
  const makeAdder = (n) => (m) => n + m;         // closures over the defining scope

  return { stdout: `${total} ${label("x")} ${doubled.join(",")} ${makeAdder(1)(2)}\n` };
}

