function nonTailRecursion(n) {
    if (n <= 1) {
        return 1;
    } 

    return n * nonTailRecursion(n - 1);
}

function tailRecursion(n, acc) {
    if (acc == null){
        acc = 1
    }

    if (n <= 1) {
        return acc;
    } 

    return tailRecursion(n - 1, acc * n);
}

function sumArray(arr, i = 0, acc = 0) {
  if (i == arr.length) {
    return acc;
  }
  return sumArray(arr, i + 1, acc + arr[i]);
}

function collatz(n, steps = 0) {
  if (n == 1){ 
    return steps;
  }
  return collatz(n % 2 == 0 ? n / 2 : 3 * n + 1, steps + 1);
}

function product(a, b, acc = 1) {
  if (a > b){
    return acc;
  }
  return product(a + 1, b, acc * a);
}

function pow(base, exp, acc = 1) {
  if (exp == 0) {
    return acc;
  } 
  return pow(base, exp - 1, acc * base);
}

